-- Class notes synopsis batch 8: Clove through Cramp Bark

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Clove</strong> is a <strong>pungent</strong>, <strong>antimicrobial</strong>, <strong>anthelmintic</strong> herb that inhibits <strong>H. pylori</strong> (<strong>peptic ulcer</strong>) and removes parasites such as amoebas, tapeworms, and GI worms - high doses require <strong>kidney</strong> support and awareness of Herx die-off reactions. Used in Four Thieves Vinegar as an <strong>antimicrobial</strong>. <strong>Hazardous as EO/hydrosol on skin - skin irritant.</strong> In the traditional Hibiscus Refresher with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, orange peel, and <a href="?herb=73"><strong>Hawthorn</strong></a> L/F; in Red Drank with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, and honey/brown sugar; in a hibiscus decoction with <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, and okra slime.$$
WHERE common_name = 'Clove';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Coffee</strong> is a <strong>nervine stimulant</strong>, <strong>diuretic</strong>, and <strong>styptic</strong> (stops bleeding) - listed alongside <a href="?herb=47"><strong>Cayenne</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, and <a href="?herb=71"><strong>Shepherd's Purse</strong></a> for profuse bleeding. <strong>Anti-aging</strong>: tightens skin, brings blood to the skin, and <strong>anti-inflammatory</strong> (both green and roasted coffee; green may help more with collagen production). As a diuretic, will slowly deplete the body of important electrolytes (potassium) through the urine.$$
WHERE common_name = 'Coffee';

-- Comfrey id=89: wound care and cancer context
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Comfrey</strong> is a <strong>vulnerary</strong>, <strong>demulcent</strong>, <strong>nervine</strong>, and <strong>anti-inflammatory</strong> herb - "herbal stitches" that proliferates <strong>cell regeneration</strong>; incredible for <strong>scrapes and abrasions</strong>. <strong>NO comfrey ever for deep wounds - closes up the wound and leaves the bad underneath.</strong> Use a separate Comfrey + <a href="?herb=831"><strong>Helichrysum</strong></a> salve for skin healing only, after antimicrobial treatment is complete. Comfrey root as <strong>demulcent</strong> for <strong>upper GI excess</strong>. Listed as <strong>nervine</strong> and <strong>anti-inflammatory</strong> for <strong>cancer</strong> support; in anti-cancer formula 2 (more intense, used in stages after formula 1).$$
WHERE id = 89;

-- Comfrey id=1650: African American and historical herbalism context
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Comfrey</strong> is one of the essential herbs of the Middle Ages in western European herbalism. In traditional African American herbalism: leaves prepared as an infusion; in the traditional African American glycerine syrup for <strong>pain</strong>, <strong>fever</strong>, and <strong>swelling</strong> combined with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=56"><strong>Sage</strong></a>, and a flavonoid addition; in a historical formula for <strong>immune support</strong> with <a href="?herb=56"><strong>Sage</strong></a> and <a href="?herb=84"><strong>Chamomile</strong></a> (cami weed). For <strong>eczema</strong>: used as a wash or oil; soothing especially in the "itch that rashes" phase; also as <strong>vulnerary</strong> for <strong>shallow wounds</strong>.$$
WHERE id = 1650;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cordyceps</strong> is an <strong>adaptogen</strong> (non-toxic at high doses, produces non-specific resistance to stress, regulates the H-P-A axis) and an energy and vitality mushroom - increases <strong>oxygen</strong> and <strong>mobility</strong>; more about energy where <a href="?herb=2632"><strong>Lion's Mane Mushroom</strong></a> and <a href="?herb=11"><strong>Reishi Mushroom</strong></a> are more about focus. Paul Stamets recommends fruiting bodies; "Real Mushrooms" company noted.$$
WHERE common_name = 'Cordyceps';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Coriander</strong> is a <strong>cooling</strong> spice listed for <strong>Hot constitution</strong> - a classic combination with cumin and <a href="?herb=76"><strong>Fennel</strong></a> for inflamed conditions; a smaller source of <strong>Vitamin A / Beta carotene</strong>. Among warming digestive herbs for rekindling digestive fire alongside <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=76"><strong>Fennel</strong></a>, cumin, <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=172"><strong>Artichoke</strong></a> leaf, and orange peel.$$
WHERE common_name = 'Coriander';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Corn Silk</strong> (Zea mays, silk and husk) is a <strong>demulcent</strong>, <strong>nervine</strong>, <strong>anti-inflammatory</strong>, and <strong>lymphatic</strong> herb for the <strong>urinary system</strong> - as a cold infusion (dried) for <strong>UTIs</strong>: "make urethra slippery" (prepared as cold infusion, not hot tea); for <strong>kidney pain</strong> and cooling <strong>inflammation in the urinary tract</strong>; for <strong>electrolytes</strong> and urinary support. Used in traditional Black American herbalism (shuck/husk) for <strong>measles</strong>, <strong>malaria</strong>, and <strong>smallpox</strong> (lymphatic). Nervine and anti-inflammatory for <strong>cancer</strong> support. In a regenerative tea blend with <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, and <a href="?herb=42"><strong>Red Clover</strong></a> as large daily infusions.$$
WHERE common_name = 'Corn Silk';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Corydalis</strong> is used for <strong>pain</strong> - specifically <strong>pain-induced insomnia</strong>; part of a TCM triplet with <a href="?herb=130"><strong>Wild Lettuce</strong></a> and <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a> targeting <strong>skeletal muscle injuries</strong>; a "classic sacred pairing" with <a href="?herb=2755"><strong>Dahhurian Angelica</strong></a> in TCM for <strong>gallstone/biliary pain</strong> - low dose, causes drowsiness.$$
WHERE common_name = 'Corydalis';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cotton Root Bark</strong> is a <strong>hormonal stabilizer</strong> in traditional Black American herbal practices, including in Shereel's 2022 cancer report.$$
WHERE common_name = 'Cotton Root Bark';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cramp Bark</strong> (Viburnum opulus) is a <strong>smooth muscle antispasmodic</strong> and <strong>relaxant</strong> used interchangeably with <a href="?herb=94"><strong>Black Haw</strong></a> (V. prunifolium). A primary herb for <strong>dysmenorrhea</strong> (spasmodic), <strong>endometriosis</strong> pain, <strong>amenorrhea</strong> (uterine pain in cold atonic condition), and <strong>pelvic tension</strong> - also tonifies the uterus. For <strong>threatened miscarriage</strong>: take if miscarriage sensations begin; formula 2 parts Cramp Bark to 1 part <a href="?herb=74"><strong>Wild Yam</strong></a>; dose 1/2-1 tsp every 30 minutes for up to 4 hours; up to twice a day for up to 3 days; supports miscarriage-prone individuals. <strong>Avoid Red Raspberry for miscarriage-prone patients - astringency can tighten the uterus.</strong> For <strong>hypertension in pregnancy</strong>: long folk use for gestational hypertension; relaxes the tissues. For GI: <strong>antispasmodic</strong> for <strong>cramping</strong> and <strong>spasm</strong>; severe antispasmodic support for <strong>diarrhea</strong>; smooth muscle relaxant for <strong>constipation</strong> alongside <a href="?herb=74"><strong>Wild Yam</strong></a>. For <strong>female reproductive excess</strong> (cools the system) and <strong>male reproductive excess</strong>. Dosage: cold infusion or decoction 3-4 oz up to 4x/day; tincture 30-90 drops; for miscarriage protocol 1/2-1 tsp every 30-60 min.$$
WHERE common_name = 'Cramp Bark';
